// The shape of zh-chars.json (generated by scripts/gen-zh-chars.mjs), so
// TypeScript doesn't infer a type with ten thousand keys from the file.

/** [meaning (Unihan kDefinition), Mandarin readings (kMandarin),
 *  radical-stroke (kRSUnicode), total strokes, traditional forms,
 *  simplified forms]. */
export type ZhCharRow = [string, string, string, number, string, string];

declare const data: {
  _source: string;
  _license: string;
  chars: Record<string, ZhCharRow>;
};
export default data;
